public IronsSpellbooks(IEventBus modEventBus, ModContainer modContainer) {

    ModSetup.setup();

    MAGIC_MANAGER = new MagicManager();
    MagicHelper.MAGIC_MANAGER = MAGIC_MANAGER;

    modEventBus.addListener(ModSetup::init);
